import os
import shutil
from datetime import datetime
from pathlib import Path

# Chrome's per-instance lock files; copying them makes the new instance think the profile is in use.
_LOCK_FILES = ("SingletonLock", "SingletonSocket", "SingletonCookie", "RunningChromeVersion")
# Regenerated by Chrome; leaving them out keeps the pristine copy small.
_CACHES = ("Cache", "Code Cache", "GPUCache", "DawnGraphiteCache", "DawnWebGPUCache", "ShaderCache")
# Browsing data Chrome creates even during setup (e.g. Google's NID cookie from its own background
# requests). Never kept, so every session starts with an empty jar, history and storage.
_BROWSING_DATA = (
    "Cookies", "Cookies-journal", "History", "History-journal", "Visited Links", "Top Sites", "Top Sites-journal",
    "Favicons", "Favicons-journal", "Local Storage", "Session Storage", "Sessions", "IndexedDB", "Service Worker",
    "Network Persistent State", "TransportSecurity", "Trust Tokens", "Trust Tokens-journal", "Shared Dictionary",
    "Reporting and NEL", "Reporting and NEL-journal", "Network",
)  # fmt: skip


def create_session_dir(root: Path, now: datetime) -> Path:
    """Create sessions/<timestamp>[-n] readable only by the current user (it will hold secrets)."""
    root.mkdir(parents=True, exist_ok=True)
    stem = now.strftime("%Y%m%d-%H%M%S")
    path = root / stem
    suffix = 1
    while path.exists():
        path = root / f"{stem}-{suffix}"
        suffix += 1
    path.mkdir(mode=0o700)
    path.chmod(0o700)
    return path


def profile_in_use(profile: Path) -> bool:
    """Chrome's SingletonLock is a symlink to '<host>-<pid>' while that Chrome runs."""
    lock = profile / "SingletonLock"
    if not lock.is_symlink():
        return False
    try:
        pid = int(os.readlink(lock).rsplit("-", 1)[-1])
        os.kill(pid, 0)
    except (ValueError, ProcessLookupError):
        return False
    except PermissionError:
        return True
    return True


def save_pristine(live: Path, pristine: Path) -> None:
    """Remember the freshly set-up profile (extension installed, nothing browsed)."""
    staging = pristine.with_name(pristine.name + ".tmp")
    shutil.rmtree(staging, ignore_errors=True)
    skip = shutil.ignore_patterns(*_LOCK_FILES, *_CACHES, *_BROWSING_DATA)
    shutil.copytree(live, staging, symlinks=True, ignore=skip)
    shutil.rmtree(pristine, ignore_errors=True)
    staging.rename(pristine)


def restore_pristine(pristine: Path, live: Path) -> None:
    """Reset the capture profile at the SAME path: Chrome signs settings with the path, so a moved
    profile can lose the extension. Everything browsed since setup is discarded."""
    if not pristine.is_dir():
        raise FileNotFoundError(f"No pristine profile at {pristine}")
    if profile_in_use(live):
        raise RuntimeError("The capture Chrome is still running. Quit it (Cmd+Q) and try again.")
    shutil.rmtree(live, ignore_errors=True)
    # Also filtered here so pristine copies saved by older versions come back clean.
    shutil.copytree(pristine, live, symlinks=True, ignore=shutil.ignore_patterns(*_LOCK_FILES, *_BROWSING_DATA))
